package org.eclipse.rdf4j.sail.lmdb.evaluation;

/**
 * The time one selected strategy spends producing rows, reported to the {@link LmdbNativeAdvisoryLearner} when its run
 * completes. Only pulls are timed, so a slow consumer of the results is not charged to the strategy. The first pulls
 * are timed one by one and later ones are sampled, which keeps a row loop's clock reads rare. A run that fails, is
 * cancelled or closes early never reports.
 */
final class LmdbNativeCostObservation {

	private static final long TIMED_PULLS = 64L;
	private static final long SAMPLE_INTERVAL = 16L;

	private final LmdbNativeAdvisoryLearner learner;
	private final LmdbNativeAdvisoryLearner.Key key;
	private final double expectedNanos;
	private long pulls;
	private long nanos;
	private boolean completed;

	LmdbNativeCostObservation(LmdbNativeAdvisoryLearner learner, LmdbNativeAdvisoryLearner.Key key,
			double expectedNanos) {
		this.learner = learner;
		this.key = key;
		this.expectedNanos = expectedNanos;
	}

	/** The time the opener took, which is the whole run of a strategy that materializes while it opens. */
	void opened(long openNanos) {
		nanos += openNanos;
	}

	/** Starts a pull; the result goes back to {@link #endPull(long)}. */
	long beginPull() {
		long pull = ++pulls;
		return pull <= TIMED_PULLS || pull % SAMPLE_INTERVAL == 0L ? System.nanoTime() : 0L;
	}

	void endPull(long started) {
		if (started != 0L) {
			long elapsed = System.nanoTime() - started;
			nanos += pulls <= TIMED_PULLS ? elapsed : elapsed * SAMPLE_INTERVAL;
		}
	}

	/** The run reached the end of its rows. Reports once. */
	void completed() {
		if (!completed) {
			completed = true;
			learner.observe(key, expectedNanos, nanos);
		}
	}

	/** {@code cursor} with its pulls timed; its end completes this observation. */
	NativeResultCursor observed(NativeResultCursor cursor) {
		return new NativeResultCursor() {
			@Override
			public NativeResultRow next() {
				long started = beginPull();
				NativeResultRow row = cursor.next();
				endPull(started);
				if (row == null) {
					completed();
				}
				return row;
			}

			@Override
			public NativeCancellationToken cancellation() {
				return cursor.cancellation();
			}

			@Override
			public NativeExecutionContext executionContext() {
				return cursor.executionContext();
			}

			@Override
			public boolean requestCancellation() {
				return cursor.requestCancellation();
			}

			@Override
			public void close() {
				cursor.close();
			}
		};
	}
}
